1	const PROCESSING_FEE = 5;
2	const FIRST_INSURANCE_SURCHARGE_RATE = 0.1;
3	
4	const BASE_PREMIUM: Record<string, number> = {
5	  sword: 100,
6	  amulet: 60,
7	  staff: 80,
8	  potion: 40,
9	};
10	
11	type Item = { type: string };
12	type Scenario = {
13	  customer: { yearsWithMHPCO: number };
14	  steps: Array<{ op: "quote"; items: Item[] }>;
15	};
16	
17	const itemPremium = (item: Item): number =>
18	  BASE_PREMIUM[item.type] * (1 + FIRST_INSURANCE_SURCHARGE_RATE);
19	
20	const roundUpInFavorOfInsurer = (amount: number): number =>
21	  Math.ceil(Math.round(amount * 1e6) / 1e6);
22	
23	const quotePremium = (items: Item[]): number => {
24	  const itemsTotal = items.reduce((sum, item) => sum + itemPremium(item), 0);
25	  return roundUpInFavorOfInsurer(itemsTotal + PROCESSING_FEE);
26	};
27	
28	export const runScenario = (scenario: unknown): unknown => {
29	  const { steps } = scenario as Scenario;
30	  const results = steps.map((step) => ({ premium: quotePremium(step.items) }));
31	  return { results };
32	};
